UPDATE characters c SET
  name         = u.new_name,
  title        = u.new_title,
  universe     = u.new_universe,
  version      = NULL,
  description  = '',
  actor        = NULL,
  abilities    = u.new_abilities,
  palette      = u.new_palette,
  metadata     = u.new_meta,
  category     = 'apex',
  image_url    = NULL,
  thumbnail_url = NULL,
  image_source  = NULL,
  image_license = NULL,
  image_credit  = NULL,
  wiki_title    = NULL,
  wiki_url      = NULL
FROM apex_updates u
WHERE c.id = u.id;

