UPDATE characters c SET
  name         = u.new_name,
  title        = u.new_title,
  universe     = u.new_universe,
  version      = NULL,
  description  = '',
  actor        = NULL,
  abilities    = u.new_abilities,
  palette      = u.new_palette,
  metadata     = u.new_meta,
  category     = 'vigil',
  image_url    = NULL,
  thumbnail_url = NULL,
  image_source  = NULL,
  image_license = NULL,
  image_credit  = NULL,
  wiki_title    = NULL,
  wiki_url      = NULL
FROM vigil_updates u
WHERE c.id = u.id;

-- ────────────────────────────────────────────────────────────────────────────
-- 3. Rename category_ids in rooms and games
-- ────────────────────────────────────────────────────────────────────────────

UPDATE rooms
SET category_ids = array_replace(
      array_replace(category_ids, 'marvel', 'apex'),
      'dc', 'vigil')
WHERE category_ids && ARRAY['marvel','dc'];

UPDATE games
SET category_ids = array_replace(
      array_replace(category_ids, 'marvel', 'apex'),
      'dc', 'vigil')
WHERE category_ids && ARRAY['marvel','dc'];

-- ────────────────────────────────────────────────────────────────────────────
-- 4. Verification
-- ────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
  apex_count  int;
  vigil_count int;
  old_count   int;
  null_img    int;
BEGIN
  SELECT COUNT(*) INTO apex_count  FROM characters WHERE category = 'apex';
  SELECT COUNT(*) INTO vigil_count FROM characters WHERE category = 'vigil';
  SELECT COUNT(*) INTO old_count   FROM characters WHERE category IN ('marvel','dc');
  SELECT COUNT(*) INTO null_img    FROM characters
    WHERE category IN ('apex','vigil') AND image_url IS NOT NULL;

  ASSERT apex_count  = 60, 'Expected 60 apex rows, got '  || apex_count;
  ASSERT vigil_count = 60, 'Expected 60 vigil rows, got ' || vigil_count;
  ASSERT old_count   = 0,  'Old marvel/dc rows remain: '  || old_count;
  ASSERT null_img    = 0,  'image_url not cleared on '     || null_img || ' rows';

  RAISE NOTICE 'Migration 0042 verified: % apex, % vigil, 0 old, 0 images.',
    apex_count, vigil_count;
END $$;
